using Microsoft.Data.Sqlite;
using RagnarokCompanion.Services;
using Xunit;
namespace RagnarokCompanion.Tests;
public sealed class ItemTooltipTests {
 [Fact] public async Task LocalHoverUsesCachedPortugueseDescriptionWithHonestSource(){var service=new ItemDescriptionService();var first=service.GetAsync(2255);Assert.Same(first,service.GetAsync(2255));var result=await first;Assert.Contains("FOR +1",result.RawText);Assert.Contains("bRO",result.Source);Assert.Contains("não confirmadas",result.Source);Assert.DoesNotContain("^0000ff",RagnarokDescriptionFormatter.PlainText(result.RawText),StringComparison.OrdinalIgnoreCase);}
 [Fact] public async Task AuthorizedOverridesTakePriorityWithoutChangingOriginalDescription(){var root=Path.Combine(Path.GetTempPath(),"tooltip-test-"+Guid.NewGuid());Directory.CreateDirectory(root);var database=Path.Combine(root,"items.sqlite");using(var db=new SqliteConnection("Data Source="+database)){db.Open();using var command=db.CreateCommand();command.CommandText="CREATE TABLE items(id INTEGER PRIMARY KEY);INSERT INTO items VALUES(2255);CREATE TABLE item_descriptions(item_id INTEGER PRIMARY KEY,raw_text TEXT,source TEXT);INSERT INTO item_descriptions VALUES(2255,'Descrição bRO original','bRO.lua')";command.ExecuteNonQuery();}var json=Path.Combine(root,"authorized.json");File.WriteAllText(json,"""[{"Id":2255,"Description":"^FF0000Texto especial da fixture +9%.^000000"}]""");ItemDescriptionService.ImportAuthorized(database,json);var result=await new ItemDescriptionService(database).GetAsync(2255);Assert.Contains("+9%",result.RawText);Assert.Contains("ADM",result.Source);using var verify=new SqliteConnection("Data Source="+database);verify.Open();using var read=verify.CreateCommand();read.CommandText="SELECT raw_text FROM item_descriptions WHERE item_id=2255";Assert.Equal("Descrição bRO original",read.ExecuteScalar());}
}
